diff --git a/default.properties b/default.properties
index 374f1dd71..1a57ee41f 100644
--- a/default.properties
+++ b/default.properties
@@ -70,12 +70,12 @@ compile.optimize = true
 # In particular, if you use JDK 1.4+ the generated classes will not be usable
 # for a 1.1 Java VM unless you explicitly set this attribute to the value 1.1 
 # (which is the default value for JDK 1.1 to 1.3).
-compile.target = 1.6
+compile.target = 1.8

 # Specifies the source version for the Java compiler.
 # Corresponds to the source attribute for the ant javac task. 
 # Valid values are 1.3, 1.4, 1.5. 
-compile.source = 1.6
+compile.source = 1.8

 # Specifies the source encoding.
 compile.encoding = ISO-8859-1
diff --git a/src/main/java/org/apache/commons/lang3/time/FastDateParser.java b/src/main/java/org/apache/commons/lang3/time/FastDateParser.java
index a01159bdb..e849d9434 100644
--- a/src/main/java/org/apache/commons/lang3/time/FastDateParser.java
+++ b/src/main/java/org/apache/commons/lang3/time/FastDateParser.java
@@ -302,15 +302,23 @@ public class FastDateParser implements DateParser, Serializable {
      */
     private static StringBuilder escapeRegex(StringBuilder regex, String value, boolean unquote) {
         boolean wasWhite= false;
+        int whiteCount= 0;
         for(int i= 0; i<value.length(); ++i) {
             char c= value.charAt(i);
             if(Character.isWhitespace(c)) {
                 if(!wasWhite) {
                     wasWhite= true;
-                    regex.append("\\s*+");
+                    whiteCount= 1;
+                } else {
+                    whiteCount++;
                 }
                 continue;
             }
+            if(wasWhite) {
+                for(int j= 0; j<whiteCount; j++) {
+                    regex.append("\\s");
+                }
+            }
             wasWhite= false;
             switch(c) {
             case '\'':
@@ -339,6 +347,11 @@ public class FastDateParser implements DateParser, Serializable {
             }
             regex.append(c);
         }
+        if(wasWhite) {
+            for(int j= 0; j<whiteCount; j++) {
+                regex.append("\\s");
+            }
+        }
         return regex;
     }
